class TestRestFetchStatuslines:
    def _seed_sessions(self, client: AgentPulseClient) -> None:
        for sid in ("s1", "s2"):
            client._sessions[sid] = {
                "session_id": sid,
                "today_cost_usd": 0.0,
                "session_total_cost_usd": 0.0,
                "context_used_pct": 0,
                "model_display_name": "",
                "total_input_tokens": 0,
                "total_output_tokens": 0,
                "lines_added": 0,
                "lines_removed": 0,
            }

    def test_uses_log_endpoint_with_since_midnight_and_order_desc(self) -> None:
        client = _make_client()
        self._seed_sessions(client)
        captured: dict[str, str] = {}

        def fake_urlopen(url, timeout):  # noqa: ARG001
            captured["url"] = url
            return _mock_urlopen([])

        with patch("urllib.request.urlopen", side_effect=fake_urlopen):
            client._rest_fetch_statuslines()

        assert "/api/v2/log/statuslines?since=" in captured["url"]
        assert "&order=desc&limit=1000" in captured["url"]

    def test_applies_latest_per_session(self) -> None:
        client = _make_client()
        self._seed_sessions(client)
        # Descending id order: latest first per session
        rows = [
            {
                "id": 200,
                "session_id": "s1",
                "total_input_tokens": 9999,
                "total_output_tokens": 1111,
                "lines_added": 50,
                "lines_removed": 5,
            },
            {
                "id": 199,
                "session_id": "s1",
                "total_input_tokens": 1,
                "total_output_tokens": 1,
                "lines_added": 1,
                "lines_removed": 1,
            },
            {
                "id": 198,
                "session_id": "s2",
                "total_input_tokens": 200,
                "total_output_tokens": 100,
                "lines_added": 20,
                "lines_removed": 2,
            },
        ]
        with patch("urllib.request.urlopen", return_value=_mock_urlopen(rows)):
            client._rest_fetch_statuslines()
        # s1 gets the LATEST (id 200), older s1 row ignored
        assert client._sessions["s1"]["total_input_tokens"] == 9999
        assert client._sessions["s1"]["lines_added"] == 50
        # s2 picks up its only row
        assert client._sessions["s2"]["total_input_tokens"] == 200

    def test_skips_unknown_sessions(self) -> None:
        client = _make_client()
        self._seed_sessions(client)
        rows = [
            {"id": 1, "session_id": "ghost", "total_input_tokens": 999},
        ]
        with patch("urllib.request.urlopen", return_value=_mock_urlopen(rows)):
            client._rest_fetch_statuslines()
        assert "ghost" not in client._sessions

    def test_empty_response_no_op(self) -> None:
        client = _make_client()
        self._seed_sessions(client)
        with patch("urllib.request.urlopen", return_value=_mock_urlopen([])):
            client._rest_fetch_statuslines()
        assert client._sessions["s1"]["total_input_tokens"] == 0


