    # --- pid_death_logged ---

    def test_pid_death_marks_matching_process_sessions_ended(self) -> None:
        client = _make_client()
        client._sessions["a"] = {
            "session_id": "a",
            "process_id": "p1",
            "source_system": "host-a",
            "ended_at": None,
            "is_active": True,
        }
        client._sessions["b"] = {
            "session_id": "b",
            "process_id": "p1",
            "source_system": "host-a",
            "ended_at": None,
            "is_active": True,
        }
        client._sessions["c"] = {
            "session_id": "c",
            "process_id": "p2",
            "source_system": "host-a",
            "ended_at": None,
            "is_active": True,
        }
        msg = {
            "type": "pid_death_logged",
            "process_id": "p1",
            "source_system": "host-a",
            "observed_at": 500.0,
        }
        client._handle_ws_message(msg)
        assert client._sessions["a"]["is_active"] is False
        assert client._sessions["a"]["ended_at"] == 500.0
        assert client._sessions["b"]["is_active"] is False
        assert client._sessions["b"]["ended_at"] == 500.0
        assert client._sessions["c"]["is_active"] is True
        assert client._sessions["c"]["ended_at"] is None

    def test_pid_death_requires_source_system_match(self) -> None:
        """Defense in depth: same process_id on a different host is a no-op."""
        client = _make_client()
        client._sessions["a"] = {
            "session_id": "a",
            "process_id": "p1",
            "source_system": "host-a",
            "ended_at": None,
            "is_active": True,
        }
        msg = {
            "type": "pid_death_logged",
            "process_id": "p1",
            "source_system": "host-b",
            "observed_at": 500.0,
        }
        client._handle_ws_message(msg)
        assert client._sessions["a"]["is_active"] is True
        assert client._sessions["a"]["ended_at"] is None

