class TestRestFetchEdgeCases:
    def test_rest_fetch_ignores_non_list_response(self) -> None:
        client = _make_client()
        client._sessions["existing"] = {"session_id": "existing"}
        with patch(
            "urllib.request.urlopen",
            return_value=_mock_urlopen({"unexpected": "shape"}),
        ):
            client._rest_fetch()
        # Non-list response leaves state unchanged
        assert "existing" in client._sessions

    def test_fetch_session_one_ignores_non_dict_response(self) -> None:
        client = _make_client()
        with patch("urllib.request.urlopen", return_value=_mock_urlopen([1, 2, 3])):
            client._fetch_session_one("x")
        assert "x" not in client._sessions

    def test_fetch_session_one_ignores_dict_without_session_id(self) -> None:
        client = _make_client()
        with patch(
            "urllib.request.urlopen",
            return_value=_mock_urlopen({"cwd": "/tmp"}),
        ):
            client._fetch_session_one("x")
        assert "x" not in client._sessions

    def test_rest_fetch_limits_ignores_non_list(self) -> None:
        client = _make_client()
        with patch(
            "urllib.request.urlopen",
            return_value=_mock_urlopen({"unexpected": "shape"}),
        ):
            client._rest_fetch_limits()
        assert client._limits == {}

    def test_rest_fetch_limits_ignores_non_dict_row(self) -> None:
        client = _make_client()
        with patch(
            "urllib.request.urlopen", return_value=_mock_urlopen(["not-a-dict"])
        ):
            client._rest_fetch_limits()
        assert client._limits == {}
